WITH scored AS (SELECT *, STDDEV_SAMP(balance) OVER (PARTITION BY account_type) account_type_stddev_samp_balance, AVG(balance) OVER (PARTITION BY status ORDER BY balance, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) balance_avg_5 FROM accounts) SELECT CASE WHEN account_type_stddev_samp_balance >= 81726 THEN 'LARGE' ELSE 'SMALL' END AS account_type_stddev_samp_balance_tier, status, PERCENTILE_APPROX(balance_avg_5, 0.9) AS balance_avg_5_p90, COUNT(CASE WHEN status = 'OPEN' THEN 1 END) AS open_count, COUNT(CASE WHEN status = 'OPEN' THEN 1 END) AS open_count_2 FROM scored GROUP BY CASE WHEN account_type_stddev_samp_balance >= 81726 THEN 'LARGE' ELSE 'SMALL' END, status ORDER BY account_type_stddev_samp_balance_tier DESC NULLS FIRST
